import { Component, OnInit, Input , Output, EventEmitter } from '@angular/core';
import { MatSnackBar} from '@angular/material';
import { NgForm } from '@angular/forms';
import { TechnologiesService } from '../../../@Services/technologies.service';
import { TechnologiesComponent } from '../technologies.component';

@Component({
  providers:[TechnologiesComponent],
  selector: 'app-form-add-technologies',
  templateUrl: './form-add-technologies.component.html'
  
})
export class FormAddTechnologiesComponent implements OnInit {

  @Input() technologie = { id:'', nomTechnologie: '' };
  @Input() validationError = false;

  constructor(
    private technologiesService: TechnologiesService,
    private technologiesComponent: TechnologiesComponent,
    private snackBar: MatSnackBar) { }

  //Ajouter une technologie (SANS REFRESH DE LA TABLE DES TECHNOLOGIES)
  addTechnologieController(technologieForm: NgForm) {
    this.technologiesService.addTechnologieService(this.technologie)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        { this.validationError = true; }
      else
        { this.openSnackBar("Technologie ajoutée", "OK"); }
      }
      )
      technologieForm.resetForm();  
      
  }

  //Affiche une Notification SnackBar en bas de l'écran
  openSnackBar(message: string, action: string) {
    this.snackBar.open(message, action, {
      duration: 2000,
      panelClass: ['snackbar']
    });
  }

  //Cache le message de validation 
  hideError(){
    this.validationError=false;
  }

  ngOnInit() {
  }

}
