import { Component, OnInit, ViewChild, Input, Inject } from '@angular/core';
import { MatTableDataSource, MatPaginator, MatSort, MatSnackBar} from '@angular/material';
import { MatDialog,MatDialogConfig, MAT_DIALOG_DATA,MatDialogRef } from '@angular/material';
import { NgForm, Validators } from '@angular/forms';
import { TechnologiesService } from '../../@Services/technologies.service';
import { Technologie } from '../../@Models/technologie';

export interface DialogData {
  technologie : string;
}

@Component({
  selector: 'app-technologies',
  templateUrl: './technologies.component.html'
})

export class TechnologiesComponent implements OnInit {

  constructor(
    private technologiesService: TechnologiesService,
    private snackBar: MatSnackBar,
    public dialog: MatDialog) {}

  //Initialisations concernant la MatTable
  dataSource = new MatTableDataSource<Technologie>();
  displayedColumns: string[] = ['id', 'nomTechnologie', 'supprimerTechnologie', 'modifierTechnologie'];

  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;

  @Input() technologie = { id:'', nomTechnologie: '' };
  @Input() technologieToUpdate = { id:'', nomTechnologie: '' };
  @Input() validationError = false;

  //Afficher toutes les technologies : remplissage de la table
  getAllTechnologiesController(): void {
    this.technologiesService.getAllTechnologiesService()
    .subscribe(res => {
      this.dataSource.data = res;
    })
  }
  //Ajouter une technologie + refresh de la table
  addTechnologieController(technologieForm: NgForm) {
    this.technologiesService.addTechnologieService(this.technologie)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllTechnologiesController();this.openSnackBar("Technologie ajoutée", "OK");}
      }
      )
      technologieForm.resetForm();     
  }

  //Modifier une technologie
  editTechnologieController() {
    this.technologiesService.editTechnologieService(this.technologieToUpdate)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllTechnologiesController();this.openSnackBar("Technologie modifiée", "OK");}
      }
      )
  }

  //Supprimer une technologie
  deleteTechnologieController(id) {
    //Je dois passer le ID dans un RequestBody : pour la sécurité
    //this.technologie.id = id;
    //this.technologiesService.deleteTechnologieService(this.technologie)
    this.technologiesService.deleteTechnologieService(id)
    .subscribe
      (
      res => {this.getAllTechnologiesController(); this.openSnackBar("Technologie supprimée", "OK");}
      )
  }

  ngOnInit() {
    this.getAllTechnologiesController();
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  //Recherche filtrée sur la table
  filtrerTable(filterValue: string) {
    this.dataSource.filter = filterValue.trim().toLowerCase();
  }
  
  //Cache le message de validation 
  hideError(){
    this.validationError=false;
  }

  //Affiche une Notification SnackBar en bas de l'écran
  openSnackBar(message: string, action: string) {
    this.snackBar.open(message, action, {
      duration: 2000,
      panelClass: ['snackbar']
    });
  }

  //Ouvre le pop-up pour modifier une technologie
  openDialog(id, nomTechnologie): void {

    //Objet pour configurer la modale
    const dialogConfig = new MatDialogConfig();
    dialogConfig.disableClose = false;
    dialogConfig.hasBackdrop=true;
    dialogConfig.closeOnNavigation = true;

    //Objet pour déclencher l'ouverture de la modale
    const dialogRef = this.dialog.open(EditTechnologieDialog, {
      width: '300px',
      height: '250px',
      data: {id: id, technologie: nomTechnologie}
    });


    //Fonction qui s'éxècute quand je ferme la modale
    dialogRef.afterClosed().subscribe(result => {
      if(result){
          this.technologieToUpdate.id=result.split("#")[0];
          this.technologieToUpdate.nomTechnologie=result.split("#")[1];
          this.editTechnologieController();
          }
    });
  }
}

@Component({
  selector: 'edit-technologie-dialog',
  templateUrl: 'editTechnologieDialog.html',
  })
  export class EditTechnologieDialog {
    constructor(@Inject(MAT_DIALOG_DATA) public data: DialogData) {}
  }
