import { Component, OnInit, ViewChild, Input, Inject } from '@angular/core';
import { MatTableDataSource, MatPaginator, MatSort, MatSnackBar} from '@angular/material';
import { MatDialog,MatDialogConfig, MAT_DIALOG_DATA,MatDialogRef } from '@angular/material';
import { NgForm, Validators } from '@angular/forms';
import { EntreprisesService } from '../../@Services/entreprises.service';
import { Entreprise } from '../../@Models/entreprise';

export interface DialogData {
  entreprise : string;
}

@Component({
  selector: 'app-entreprises',
  templateUrl: './entreprises.component.html'
})

export class EntreprisesComponent implements OnInit {

  constructor(
    private entreprisesService: EntreprisesService,
    private snackBar: MatSnackBar,
    public dialog: MatDialog) {}

  //Initialisations concernant la MatTable
  dataSource = new MatTableDataSource<Entreprise>();
  displayedColumns: string[] = ['id', 'nomEntreprise', 'supprimerEntreprise', 'modifierEntreprise'];

  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;

  @Input() entreprise = { idEntreprise:'', nomEntreprise: '' };
  @Input() entrepriseToUpdate = { idEntreprise:'', nomEntreprise: '' };
  @Input() validationError = false;

  //Afficher toutes les entreprises : remplissage de la table
  getAllEntreprisesController(): void {
    this.entreprisesService.getAllEntreprisesService()
    .subscribe(res => {
      this.dataSource.data = res;
    })
  }
  //Ajouter une entreprise + refresh de la table
  addEntrepriseController(entrepriseForm: NgForm) {
    this.entreprisesService.addEntrepriseService(this.entreprise)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllEntreprisesController();this.openSnackBar("Entreprise ajoutée", "OK");}
      }
      )
      entrepriseForm.resetForm();     
  }

  //Modifier une entreprise
  editEntrepriseController() {
    this.entreprisesService.editEntrepriseService(this.entrepriseToUpdate)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllEntreprisesController();this.openSnackBar("Entreprise modifiée", "OK");}
      }
      )
  }

  //Supprimer une entreprise
  deleteEntrepriseController(id) {
    //Je dois passer le ID dans un RequestBody : pour la sécurité
    //this.entreprise.id = id;
    //this.entreprisesService.deleteEntrepriseService(this.entreprise)
    this.entreprisesService.deleteEntrepriseService(id)
    .subscribe
      (
      res => {this.getAllEntreprisesController(); this.openSnackBar("Entreprise supprimée", "OK");}
      )
  }

  ngOnInit() {
    this.getAllEntreprisesController();
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  //Recherche filtrée sur la table
  filtrerTable(filterValue: string) {
    this.dataSource.filter = filterValue.trim().toLowerCase();
  }
  
  //Cache le message de validation 
  hideError(){
    this.validationError=false;
  }

  //Affiche une Notification SnackBar en bas de l'écran
  openSnackBar(message: string, action: string) {
    this.snackBar.open(message, action, {
      duration: 2000,
      panelClass: ['snackbar']
    });
  }

  //Ouvre le pop-up pour modifier une entreprise
  openDialog(idEntreprise, nomEntreprise): void {

    //Objet pour configurer la modale
    const dialogConfig = new MatDialogConfig();
    dialogConfig.disableClose = false;
    dialogConfig.hasBackdrop=true;
    dialogConfig.closeOnNavigation = true;

    //Objet pour déclencher l'ouverture de la modale
    const dialogRef = this.dialog.open(EditEntrepriseDialog, {
      width: '300px',
      height: '250px',
      data: {idEntreprise: idEntreprise, nomEntreprise: nomEntreprise}
    });


    //Fonction qui s'éxècute quand je ferme la modale
    dialogRef.afterClosed().subscribe(result => {
      if(result){
          this.entrepriseToUpdate.idEntreprise=result.split("#")[0];
          this.entrepriseToUpdate.nomEntreprise=result.split("#")[1];
          this.editEntrepriseController();
          }
    });
  }
}

@Component({
  selector: 'edit-entreprise-dialog',
  templateUrl: 'editEntrepriseDialog.html',
  })
  export class EditEntrepriseDialog {
    constructor(@Inject(MAT_DIALOG_DATA) public data: DialogData) {}
  }
