import { Component, OnInit, ViewChild, Input, Inject } from '@angular/core';
import { MatTableDataSource, MatPaginator, MatSort, MatSnackBar} from '@angular/material';
import { MatDialog,MatDialogConfig, MAT_DIALOG_DATA,MatDialogRef } from '@angular/material';
import { NgForm, Validators } from '@angular/forms';
import { EcolesService } from '../../@Services/ecoles.service';
import { Ecole } from '../../@Models/ecole';

export interface DialogData {
  ecole : string;
}

@Component({
  selector: 'app-ecoles',
  templateUrl: './ecoles.component.html'
})

export class EcolesComponent implements OnInit {

  constructor(
    private ecolesService: EcolesService,
    private snackBar: MatSnackBar,
    public dialog: MatDialog) {}

  //Initialisations concernant la MatTable
  dataSource = new MatTableDataSource<Ecole>();
  displayedColumns: string[] = ['id', 'nomEcole', 'supprimerEcole', 'modifierEcole'];

  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;

  @Input() ecole = { id:'', nomEcole: '' };
  @Input() ecoleToUpdate = { id:'', nomEcole: '' };
  @Input() validationError = false;

  //Afficher toutes les ecoles : remplissage de la table
  getAllEcolesController(): void {
    this.ecolesService.getAllEcolesService()
    .subscribe(res => {
      this.dataSource.data = res;
    })
  }
  //Ajouter une ecole + refresh de la table
  addEcoleController(ecoleForm: NgForm) {
    this.ecolesService.addEcoleService(this.ecole)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllEcolesController();this.openSnackBar("École ajoutée", "OK");}
      }
      )
      ecoleForm.resetForm();     
  }

  //Modifier une ecole
  editEcoleController() {
    this.ecolesService.editEcoleService(this.ecoleToUpdate)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllEcolesController();this.openSnackBar("École modifiée", "OK");}
      }
      )
  }

  //Supprimer une ecole
  deleteEcoleController(id) {
    //Je dois passer le ID dans un RequestBody : pour la sécurité
    //this.ecole.id = id;
    //this.ecolesService.deleteEcoleService(this.ecole)
    this.ecolesService.deleteEcoleService(id)
    .subscribe
      (
      res => {this.getAllEcolesController(); this.openSnackBar("École supprimée", "OK");}
      )
  }

  ngOnInit() {
    this.getAllEcolesController();
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  //Recherche filtrée sur la table
  filtrerTable(filterValue: string) {
    this.dataSource.filter = filterValue.trim().toLowerCase();
  }
  
  //Cache le message de validation 
  hideError(){
    this.validationError=false;
  }

  //Affiche une Notification SnackBar en bas de l'écran
  openSnackBar(message: string, action: string) {
    this.snackBar.open(message, action, {
      duration: 2000,
      panelClass: ['snackbar']
    });
  }

  //Ouvre le pop-up pour modifier une ecole
  openDialog(id, nomEcole): void {

    //Objet pour configurer la modale
    const dialogConfig = new MatDialogConfig();
    dialogConfig.disableClose = false;
    dialogConfig.hasBackdrop=true;
    dialogConfig.closeOnNavigation = true;

    //Objet pour déclencher l'ouverture de la modale
    const dialogRef = this.dialog.open(EditEcoleDialog, {
      width: '300px',
      height: '250px',
      data: {id: id, ecole: nomEcole}
    });


    //Fonction qui s'éxècute quand je ferme la modale
    dialogRef.afterClosed().subscribe(result => {
      if(result){
          this.ecoleToUpdate.id=result.split("#")[0];
          this.ecoleToUpdate.nomEcole=result.split("#")[1];
          this.editEcoleController();
          }
    });
  }
}

@Component({
  selector: 'edit-ecole-dialog',
  templateUrl: 'editEcoleDialog.html',
  })
  export class EditEcoleDialog {
    constructor(@Inject(MAT_DIALOG_DATA) public data: DialogData) {}
  }
