import { Component, OnInit, ViewChild, Input, Inject } from '@angular/core';
import { MatTableDataSource, MatPaginator, MatSort, MatSnackBar} from '@angular/material';
import { MatDialog,MatDialogConfig, MAT_DIALOG_DATA,MatDialogRef } from '@angular/material';
import { NgForm, Validators } from '@angular/forms';
import { CertificationsService } from '../../@Services/certifications.service';
import { Certification } from '../../@Models/certification';

export interface DialogData {
  certification : string;
}

@Component({
  selector: 'app-certifications',
  templateUrl: './certifications.component.html'
})

export class CertificationsComponent implements OnInit {

  constructor(
    private certificationsService: CertificationsService,
    private snackBar: MatSnackBar,
    public dialog: MatDialog) {}

  //Initialisations concernant la MatTable
  dataSource = new MatTableDataSource<Certification>();
  displayedColumns: string[] = ['id', 'nomCertification', 'supprimerCertification', 'modifierCertification'];

  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;

  @Input() certification = { id:'', nomCertification: '' };
  @Input() certificationToUpdate = { id:'', nomCertification: '' };
  @Input() validationError = false;

  //Afficher toutes les certifications : remplissage de la table
  getAllCertificationsController(): void {
    this.certificationsService.getAllCertificationsService()
    .subscribe(res => {
      this.dataSource.data = res;
    })
  }
  //Ajouter une certification + refresh de la table
  addCertificationController(certificationForm: NgForm) {
    this.certificationsService.addCertificationService(this.certification)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllCertificationsController();this.openSnackBar("Certification ajoutée", "OK");}
      }
      )
      certificationForm.resetForm();     
  }

  //Modifier une certification
  editCertificationController() {
    this.certificationsService.editCertificationService(this.certificationToUpdate)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllCertificationsController();this.openSnackBar("Certification modifiée", "OK");}
      }
      )
  }

  //Supprimer une certification
  deleteCertificationController(id) {
    //Je dois passer le ID dans un RequestBody : pour la sécurité
    //this.certification.id = id;
    //this.certificationsService.deleteCertificationService(this.certification)
    this.certificationsService.deleteCertificationService(id)
    .subscribe
      (
      res => {this.getAllCertificationsController(); this.openSnackBar("Certification supprimée", "OK");}
      )
  }

  ngOnInit() {
    this.getAllCertificationsController();
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  //Recherche filtrée sur la table
  filtrerTable(filterValue: string) {
    this.dataSource.filter = filterValue.trim().toLowerCase();
  }
  
  //Cache le message de validation 
  hideError(){
    this.validationError=false;
  }

  //Affiche une Notification SnackBar en bas de l'écran
  openSnackBar(message: string, action: string) {
    this.snackBar.open(message, action, {
      duration: 2000,
      panelClass: ['snackbar']
    });
  }

  //Ouvre le pop-up pour modifier une certification
  openDialog(id, nomCertification): void {

    //Objet pour configurer la modale
    const dialogConfig = new MatDialogConfig();
    dialogConfig.disableClose = false;
    dialogConfig.hasBackdrop=true;
    dialogConfig.closeOnNavigation = true;

    //Objet pour déclencher l'ouverture de la modale
    const dialogRef = this.dialog.open(EditCertificationDialog, {
      width: '300px',
      height: '250px',
      data: {id: id, certification: nomCertification}
    });


    //Fonction qui s'éxècute quand je ferme la modale
    dialogRef.afterClosed().subscribe(result => {
      if(result){
          this.certificationToUpdate.id=result.split("#")[0];
          this.certificationToUpdate.nomCertification=result.split("#")[1];
          this.editCertificationController();
          }
    });
  }
}

@Component({
  selector: 'edit-certification-dialog',
  templateUrl: 'editCertificationDialog.html',
  })
  export class EditCertificationDialog {
    constructor(@Inject(MAT_DIALOG_DATA) public data: DialogData) {}
  }
