import { Component, OnInit, ViewChild, Input, Inject, Output, EventEmitter } from '@angular/core';
import { MatTableDataSource, MatPaginator, MatSort, MatSnackBar, MatProgressSpinnerModule} from '@angular/material';
import { MatDialog,MatDialogConfig, MAT_DIALOG_DATA,MatDialogRef } from '@angular/material';
import { NgForm, Validators } from '@angular/forms';
import { ContactsService } from '../../@Services/contacts.service';
import { Contact } from '../../@Models/contact';

import { FileUploadService } from '../../@Services/file-upload.service';
import { HttpResponse, HttpEventType } from '@angular/common/http';



@Component({
  selector: 'app-contacts',
  templateUrl: './contacts.component.html',
  styleUrls: ['./contacts.component.css'],
})

export class ContactsComponent implements OnInit {

  constructor(
    private contactsService: ContactsService,
    private snackBar: MatSnackBar,
    public dialog: MatDialog,
    private uploadService: FileUploadService) {}

  //Initialisations concernant la MatTable
  dataSource = new MatTableDataSource<Contact>();
  displayedColumns: string[] = ['urlPhoto', 'contact', 'details', 'supprimerContact', 'modifierContact'];

  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;

  contact = { id:'', identite: '', telephone: '', email: '', poste_occupe: '', description_detaillee: '', urlPhoto : '', entreprise: {idEntreprise: '', nomEntreprise:''} };
  contactToUpdate = { id:'', identite: '', telephone: '', email: '', poste_occupe: '', description_detaillee: '', urlPhoto : '', entreprise: {idEntreprise:'', nomEntreprise:''} };
  validationError = false;

  //Il va être utilisé par le DialogContact afin de mettre à jour l'Id Entreprise à éditer 
  static idEntrepriseToEdit:any;

  /**
   * 
   * FileUpload
   * 
   * 
   */
  selectedFiles: FileList;
  currentFileUpload: File;
  progress: { percentage: number } = { percentage: 0 };
  fileNameOnServer : any;
 
 
  selectFile(event) {
    this.selectedFiles = event.target.files;
  }
 
  addPhotoController(id) {

    this.progress.percentage = 0;
    this.currentFileUpload = this.selectedFiles.item(0);

    this.uploadService.addPhoto(this.currentFileUpload, id)

    .subscribe(event => {
      if (event.type === HttpEventType.UploadProgress) 
      {
        this.progress.percentage = Math.round(100 * event.loaded / event.total);
      } 
      else if (event instanceof HttpResponse) 
      {
        console.log('File is completely uploaded!');
 
      }
    });
 
    this.selectedFiles = undefined;

  }

  //Afficher touts les contacts : remplissage de la table
  getAllContactsController(): void {
    this.contactsService.getAllContactsService()
    .subscribe(res => {
      this.dataSource.data = res;
    })
  }
  //Ajouter une contact + refresh de la table
  addContactController(contactForm: NgForm) {
    this.contactsService.addContactService(this.contact)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {
          this.validationError = true;
        }
      else
        {
          this.addPhotoController(res.id);
          this.getAllContactsController();
          this.openSnackBar("Contact ajouté", "OK");}
        }
      )
      contactForm.resetForm();     
  }

  //Modifier une contact
  editContactController() {
    this.contactsService.editContactService(this.contactToUpdate)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllContactsController();this.openSnackBar("Contact modifié", "OK");}
      }
      )
  }

  //Supprimer un contact
  deleteContactController(id) {
    //Je dois passer le ID dans un RequestBody : pour la sécurité
    //this.contact.id = id;
    //this.contactsService.deleteContactService(this.contact)
    this.contactsService.deleteContactService(id)
    .subscribe
      (
      res => {this.getAllContactsController(); this.openSnackBar("Contact supprimé", "OK");}
      )
  }

  //Parent intercepte l'event envoyé par son fils : <app-liste-entreprises> qui génére un EventEmitter
  onSelectedEntrepriseId(event){
    this.contact.entreprise.idEntreprise=event;
  }


  ngOnInit() {
    this.getAllContactsController();
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  //Recherche filtrée sur la table
  filtrerTable(filterValue: string) {
    this.dataSource.filter = filterValue.trim().toLowerCase();
  }
  
  //Cache le message de validation 
  hideError(){
    this.validationError=false;
  }

  //Affiche une Notification SnackBar en bas de l'écran
  openSnackBar(message: string, action: string) {
    this.snackBar.open(message, action, {
      duration: 2000,
      panelClass: ['snackbar']
    });
  }

  //Ouvre le pop-up pour modifier une contact
  openDialog(id, identite, telephone, email, poste_occupe, description_detaillee, entreprise): void {

    //Objet pour configurer la modale
    const dialogConfig = new MatDialogConfig();
    dialogConfig.disableClose = false;
    dialogConfig.hasBackdrop=true;
    dialogConfig.closeOnNavigation = true;

    /*Objet pour déclencher l'ouverture de la modale :
    il sert à remplier les champs du formulaire de l'update
    à traver l'objet data

    */
    const dialogRef = this.dialog.open(EditContactDialog, {
      width: '600px',
      height: '500px',
      data: {
        id: id, 
        identite: identite, 
        telephone: telephone,
        email: email,  
        poste_occupe: poste_occupe, 
        description_detaillee: description_detaillee, 
        entreprise : entreprise 
      }
    });


    /*Fonction qui s'éxècute quand je ferme la modale
    Elle remplira l'objet "contactToUpdate" qui sera 
    envoyé au serveur pour faire l'update
    */
    dialogRef.afterClosed().subscribe(result => {
      if(result){
        
          this.contactToUpdate.id=result.split("#")[0];
          this.contactToUpdate.identite=result.split("#")[1];
          this.contactToUpdate.telephone=result.split("#")[2];
          this.contactToUpdate.email=result.split("#")[3];
          this.contactToUpdate.poste_occupe=result.split("#")[4];
          this.contactToUpdate.description_detaillee=result.split("#")[5];
          this.contactToUpdate.entreprise.idEntreprise=ContactsComponent.idEntrepriseToEdit;

          this.editContactController();
          }
    });
  }
}

@Component({
  selector: 'edit-contact-dialog',
  templateUrl: 'editContactDialog.html',
  })

  export class EditContactDialog {

    constructor(@Inject(MAT_DIALOG_DATA) public data: any) {}

    /*Le composant editContactDialog intercepte l'event à partir 
      de la vue puis il met à jour l'id Entreprise à envoyer en cas de 
      modification d'un contact
      J'ai dû utiliser une variable static pour cela
    */

    onSelectedEntrepriseId(event){
    ContactsComponent.idEntrepriseToEdit = event;
  }
  }
