import { Component, OnInit, ViewChild, Input, Inject } from '@angular/core';
import { MatTableDataSource, MatPaginator, MatSort, MatSnackBar, MatProgressSpinnerModule} from '@angular/material';
import { MatDialog,MatDialogConfig, MAT_DIALOG_DATA,MatDialogRef } from '@angular/material';
import { NgForm, Validators } from '@angular/forms';
import { CollaborateursService } from '../../@Services/collaborateurs.service';
import { Collaborateur } from '../../@Models/collaborateur';

export interface DialogData {
  collaborateur : string;
}

@Component({
  selector: 'app-collaborateurs',
  templateUrl: './collaborateurs.component.html',
  styleUrls: ['./collaborateurs.component.css']
})

export class CollaborateursComponent implements OnInit {

  constructor(
    private collaborateursService: CollaborateursService,
    private snackBar: MatSnackBar,
    public dialog: MatDialog) {}

  //Initialisations concernant la MatTable
  dataSource = new MatTableDataSource<Collaborateur>();
  displayedColumns: string[] = ['id', 'identite', 'email', 'login', 'password', 'supprimerCollaborateur', 'modifierCollaborateur'];

  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;

  @Input() collaborateur = { id:'', identite: '', email: '', login: '', password: '' };
  @Input() collaborateurToUpdate = { id:'', identite: '', email: '', login: '', password: '' };
  @Input() validationError = false;

  selectedFile: File;

  //Afficher touts les collaborateurs : remplissage de la table
  getAllCollaborateursController(): void {
    this.collaborateursService.getAllCollaborateursService()
    .subscribe(res => {
      this.dataSource.data = res;
    })
  }
  //Ajouter une collaborateur + refresh de la table
  addCollaborateurController(collaborateurForm: NgForm) {
    this.collaborateursService.addCollaborateurService(this.collaborateur)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllCollaborateursController();this.openSnackBar("Collaborateur ajouté", "OK");}
      }
      )
      collaborateurForm.resetForm();     
  }

  //Modifier une collaborateur
  editCollaborateurController() {
    this.collaborateursService.editCollaborateurService(this.collaborateurToUpdate)
    .subscribe
      (
      res => 
      { 
      if(res == null)
        {this.validationError = true;}
      else
        {this.getAllCollaborateursController();this.openSnackBar("Collaborateur modifié", "OK");}
      }
      )
  }

  //Supprimer une collaborateur
  deleteCollaborateurController(id) {
    //Je dois passer le ID dans un RequestBody : pour la sécurité
    //this.collaborateur.id = id;
    //this.collaborateursService.deleteCollaborateurService(this.collaborateur)
    this.collaborateursService.deleteCollaborateurService(id)
    .subscribe
      (
      res => {this.getAllCollaborateursController(); this.openSnackBar("Collaborateur supprimé", "OK");}
      )
  }

  ngOnInit() {
    this.getAllCollaborateursController();
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  //Recherche filtrée sur la table
  filtrerTable(filterValue: string) {
    this.dataSource.filter = filterValue.trim().toLowerCase();
  }
  
  //Cache le message de validation 
  hideError(){
    this.validationError=false;
  }

  //Affiche une Notification SnackBar en bas de l'écran
  openSnackBar(message: string, action: string) {
    this.snackBar.open(message, action, {
      duration: 2000,
      panelClass: ['snackbar']
    });
  }

  //Ouvre le pop-up pour modifier une collaborateur
  openDialog(id, identite, email, login, password): void {

    //Objet pour configurer la modale
    const dialogConfig = new MatDialogConfig();
    dialogConfig.disableClose = false;
    dialogConfig.hasBackdrop=true;
    dialogConfig.closeOnNavigation = true;

    //Objet pour déclencher l'ouverture de la modale
    const dialogRef = this.dialog.open(EditCollaborateurDialog, {
      width: '300px',
      height: '500px',
      data: {id: id, identite: identite, email: email, login: login, password: password}
    });


    //Fonction qui s'éxècute quand je ferme la modale
    dialogRef.afterClosed().subscribe(result => {
      if(result){
        
          this.collaborateurToUpdate.id=result.split("#")[0];
          this.collaborateurToUpdate.identite=result.split("#")[1];
          this.collaborateurToUpdate.email=result.split("#")[2];
          this.collaborateurToUpdate.login=result.split("#")[3];
          this.collaborateurToUpdate.password=result.split("#")[4];
          
          this.editCollaborateurController();
          }
    });
  }

    //Envoyer la photo du collaborateur au serveur
    onFileChanged(event) {
      this.selectedFile = event.target.files[0];
      console.log(this.selectedFile);
    }
}

@Component({
  selector: 'edit-collaborateur-dialog',
  templateUrl: 'editCollaborateurDialog.html',
  })
  export class EditCollaborateurDialog {
    constructor(@Inject(MAT_DIALOG_DATA) public data: DialogData) {}
  }
